	tests := []struct {
		name     string
		cap, rat float64
		advances []time.Duration
		n        int
		want     bool
	}{
		{"full bucket allows", 5, 1, nil, 5, true},
		{"exceeds capacity", 5, 1, nil, 6, false},
		{"partial consume then refill", 5, 1, []time.Duration{0, 3 * time.Second}, 4, true},
		{"not enough refill", 5, 1, []time.Duration{0, 2 * time.Second}, 4, false},
		{"exact refill", 5, 1, []time.Duration{0, 2 * time.Second}, 3, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, _ := NewLimiter(tt.cap, tt.rat, fc)
			// Consume initial tokens to set up state.
			if len(tt.advances) > 0 {
